  border: 1px solid transparent;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition);
}
.nav-tab:hover { border-color: rgba(255,255,255,0.6); }
.nav-tab.active { border-color: #fff; background: rgba(255,255,255,0.15); }
.nav-tab svg { width: 18px; height: 18px; flex-shrink: 0; }

/* ── Hero ── */
.hero {
  background: var(--navy);
  padding: 32px 0 48px;
  color: #fff;
}
.hero h1 { font-size: 40px; font-weight: 700; margin-bottom: 8px; line-height: 1.2; }
.hero .subtitle { font-size: 18px; opacity: 0.85; margin-bottom: 28px; }

/* Search bar */
.search-bar {
  background: var(--gold);
  border-radius: var(--radius);
  padding: 4px;
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.search-field {
  flex: 1;
  min-width: 160px;
  padding: 12px 16px;
  border: 2px solid transparent;
  border-radius: 6px;
  font-size: 14px;
  background: #fff;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition);
}
.search-field:focus { border-color: var(--blue); }
.search-field::placeholder { color: var(--text-lighter); }
.btn-search {
  background: var(--blue);
  color: #fff;
  border: none;
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
}
.btn-search:hover { background: var(--navy); }

.search-options { display: flex; gap: 16px; margin-top: 12px; flex-wrap: wrap; }
.search-options label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #fff;
  font-size: 14px;
  cursor: pointer;
}
.search-options input[type="checkbox"],
.search-options input[type="radio"] {
  accent-color: var(--gold);
  width: 16px;
  height: 16px;
}

/* ── Section ── */
.section { padding: 56px 0; }
.section-alt { background: var(--bg-white); }
.section-title { font-size: 28px; font-weight: 700; margin-bottom: 6px; }
.section-subtitle { color: var(--text-light); font-size: 16px; margin-bottom: 28px; }

/* ── Trust badges ── */
.trust-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
}
.trust-card {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 20px;
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: box-shadow var(--transition);
}
.trust-card:hover { box-shadow: var(--card-shadow-hover); }
.trust-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #EBF5FF;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--blue);
}
.trust-icon svg { width: 24px; height: 24px; }
.trust-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.trust-card p { font-size: 13px; color: var(--text-light); line-height: 1.5; }

/* ── Cards ── */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}
.card {
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: box-shadow var(--transition), transform var(--transition);
}
.card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-2px); }
.card-img {
  width: 100%;
  height: 180px;
  background: linear-gradient(135deg, #CBD5E1 0%, #94A3B8 100%);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
}
.card-body { padding: 16px; }
.card-title { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.card-location { font-size: 13px; color: var(--text-light); margin-bottom: 8px; }
.card-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.rating-badge {
  background: var(--navy);
  color: #fff;
  padding: 3px 8px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
}
.rating-text { font-size: 13px; color: var(--text-light); }
.card-price { font-size: 18px; font-weight: 700; color: var(--navy); }
.card-price .original {
  text-decoration: line-through;
  color: var(--text-lighter);
  font-weight: 400;
  font-size: 14px;
  margin-right: 6px;
}
.card-price .label { font-size: 12px; color: var(--text-light); font-weight: 400; display: block; }

/* ── Offers ── */
.offer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; }
.offer-card {
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  overflow: hidden;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.offer-card.deal {
  background: linear-gradient(135deg, var(--navy) 0%, #0050C8 100%);
  color: #fff;
}
.offer-card.rewards {
  background: linear-gradient(135deg, #1E3A5F 0%, #003060 100%);
  color: #fff;
}
.offer-card h3 { font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.offer-card p { font-size: 14px; opacity: 0.9; margin-bottom: 16px; line-height: 1.5; }
.btn-offer {
  display: inline-block;
  padding: 10px 20px;
  background: var(--gold);
  color: var(--text);
  border: none;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 14px;
  transition: background var(--transition);
  align-self: flex-start;
}
.btn-offer:hover { background: var(--gold-hover); color: var(--text); }

/* ── Property types ── */
.type-scroll {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 8px;
  scrollbar-width: thin;
}
.type-chip {
  flex-shrink: 0;
  padding: 10px 20px;
  border: 1px solid var(--border);
  border-radius: 24px;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  background: var(--bg-white);
  transition: all var(--transition);
  color: var(--text);
}
.type-chip:hover { border-color: var(--blue); color: var(--blue); background: #EBF5FF; }

/* ── Tabs ── */
.tab-bar {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  padding-bottom: 4px;
  margin-bottom: 24px;
  scrollbar-width: none;
}
.tab-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 10px 20px;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: var(--bg-white);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition);
  color: var(--text);
}
.tab-btn:hover { border-color: var(--blue); color: var(--blue); }
.tab-btn.active {
  background: var(--blue);
  color: #fff;
  border-color: var(--blue);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ── Destination grid ── */
.dest-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
.dest-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  box-shadow: var(--card-shadow);
  transition: box-shadow var(--transition), transform var(--transition);
}
.dest-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-2px); }
.dest-img {
  width: 100%;
  height: 160px;
  background: linear-gradient(135deg, #4A90D9 0%, #003B95 100%);
  display: flex;
  align-items: flex-end;
  padding: 16px;
  color: #fff;
}
.dest-card h3 { font-size: 18px; font-weight: 700; }
.dest-card .count { font-size: 13px; opacity: 0.9; }

/* Top 2 wider */
.dest-grid-mixed { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.dest-grid-mixed .dest-card .dest-img { height: 200px; }
.dest-grid-mixed + .dest-grid-3 { margin-top: 16px; }
.dest-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }

/* ── Carousel ── */
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 4px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track .card { min-width: 280px; flex-shrink: 0; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--bg-white);
  border: 1px solid var(--border);
  box-shadow: var(--card-shadow);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: all var(--transition);
  color: var(--text);
}
.carousel-btn:hover { box-shadow: var(--card-shadow-hover); background: var(--bg); }
.carousel-btn.prev { left: -16px; }
.carousel-btn.next { right: -16px; }
.carousel-btn svg { width: 20px; height: 20px; }

/* ── Trending ── */
.trending-row { display: flex; gap: 16px; flex-wrap: wrap; }
.trending-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px 8px 8px;
  border-radius: 24px;
  border: 1px solid var(--border);
  background: var(--bg-white);
  font-weight: 500;
  font-size: 14px;
  transition: all var(--transition);
}
.trending-chip:hover { border-color: var(--blue); box-shadow: var(--card-shadow); }
.trending-flag {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #CBD5E1, #94A3B8);
}

/* ── Loyalty CTA ── */
.loyalty-banner {
  background: linear-gradient(135deg, var(--navy) 0%, #0050C8 100%);
  border-radius: var(--radius-lg);
  padding: 48px;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  flex-wrap: wrap;
}
.loyalty-banner h2 { font-size: 32px; font-weight: 700; margin-bottom: 8px; }
.loyalty-banner p { font-size: 16px; opacity: 0.9; max-width: 500px; }
.loyalty-actions { display: flex; gap: 12px; flex-shrink: 0; }
.btn-primary {
  padding: 12px 28px;
  background: var(--gold);
  color: var(--text);
  border: none;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 15px;
  transition: background var(--transition);
}
.btn-primary:hover { background: var(--gold-hover); }
.btn-secondary {
  padding: 12px 28px;
  background: transparent;
  color: #fff;
  border: 2px solid rgba(255,255,255,0.5);
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 15px;
  transition: all var(--transition);
}
.btn-secondary:hover { border-color: #fff; background: rgba(255,255,255,0.1); }

/* ── Popular links ── */
.link-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
}
.link-list a {
  font-size: 14px;
  color: var(--blue);
  padding: 4px 0;
}
.link-list a:hover { text-decoration: underline; }

/* ── FAQ accordion ── */
.faq-list { max-width: 800px; }
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 8px;
  overflow: hidden;
  background: var(--bg-white);
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: none;
  border: none;
  font-size: 15px;
  font-weight: 600;
  text-align: left;
  color: var(--text);
  gap: 16px;
  transition: background var(--transition);
}
.faq-question:hover { background: var(--bg); }
.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
  color: var(--text-light);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}
.faq-answer-inner { padding: 0 20px 16px; font-size: 14px; color: var(--text-light); line-height: 1.6; }
.faq-item.open .faq-answer { max-height: 200px; }

/* ── Rental companies ── */
.company-grid {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  justify-content: center;
}
.company-logo {
  width: 120px;
  height: 60px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 14px;
  color: var(--text-light);
  background: var(--bg-white);
  transition: box-shadow var(--transition);
}
.company-logo:hover { box-shadow: var(--card-shadow-hover); }

/* ── Benefits ── */
.benefit-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
}
.benefit-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  border-radius: 50%;
  background: #EBF5FF;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--blue);
}
.benefit-icon svg { width: 28px; height: 28px; }
.benefit-card h3 { font-size: 16px; font-weight: 600; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: var(--text-light); }

/* ── Credit card promo ── */
.promo-banner {
  background: linear-gradient(135deg, #1E3A5F 0%, #003060 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 32px;
  flex-wrap: wrap;
}
.promo-banner h3 { font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.promo-banner p { font-size: 14px; opacity: 0.9; margin-bottom: 16px; }

/* ── Footer ── */
.site-footer {
  background: var(--navy);
  color: #fff;
  padding: 48px 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}
.footer-col h4 { font-size: 14px; font-weight: 600; margin-bottom: 12px; opacity: 0.8; }
.footer-col a {
  display: block;
  padding: 3px 0;
  font-size: 13px;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding-top: 20px;
  font-size: 13px;
  opacity: 0.6;
  text-align: center;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .dest-grid { grid-template-columns: repeat(3, 1fr); }
  .dest-grid-3 { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .hero h1 { font-size: 28px; }
  .search-bar { flex-direction: column; }
  .search-field { min-width: 100%; }
  .section { padding: 40px 0; }
  .section-title { font-size: 22px; }
  .loyalty-banner { padding: 32px 24px; flex-direction: column; text-align: center; }
  .loyalty-actions { justify-content: center; }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .dest-grid-mixed { grid-template-columns: 1fr; }
  .dest-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .card-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
  .header-actions { display: none; }
  .promo-banner { flex-direction: column; text-align: center; padding: 28px 20px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .dest-grid { grid-template-columns: 1fr; }
  .dest-grid-3 { grid-template-columns: 1fr; }
  .card-grid { grid-template-columns: 1fr; }
  .trust-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; scroll-behavior: auto !important; }
}
