  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: box-shadow var(--transition), transform var(--transition);
}
.card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-2px); }
.card-img {
  width: 100%;
  height: 180px;
  background: linear-gradient(135deg, #CBD5E1 0%, #94A3B8 100%);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
}
.card-body { padding: 16px; }
.card-title { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.card-location { font-size: 13px; color: var(--text-light); margin-bottom: 8px; }
.card-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.rating-badge {
  background: var(--navy);
  color: #fff;
  padding: 3px 8px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
}
.rating-text { font-size: 13px; color: var(--text-light); }
.card-price { font-size: 18px; font-weight: 700; color: var(--navy); }
.card-price .original {
  text-decoration: line-through;
  color: var(--text-lighter);
